test(coding, fixed64) {
  std::string s;
  for (int power = 0; power <= 63; power++) {
    uint64_t v = static_cast<uint64_t>(1) << power;
    putfixed64(&s, v - 1);
    putfixed64(&s, v + 0);
    putfixed64(&s, v + 1);
  }

  const char* p = s.data();
  for (int power = 0; power <= 63; power++) {
    uint64_t v = static_cast<uint64_t>(1) << power;
    uint64_t actual;
    actual = decodefixed64(p);
    assert_eq(v-1, actual);
    p += sizeof(uint64_t);

    actual = decodefixed64(p);
    assert_eq(v+0, actual);
    p += sizeof(uint64_t);

    actual = decodefixed64(p);
    assert_eq(v+1, actual);
    p += sizeof(uint64_t);
  }
}

